/// Full-width u-values for GENERATOR.
pub static U: LazyLock<Vec<[[u8; 32]; H]>> = LazyLock::new(|| {
    let raw = hex::decode(U_HEX).expect("valid hex");
    assert_eq!(raw.len(), NUM_WINDOWS * H * 32);
    raw.chunks(H * 32)
        .map(|w| std::array::from_fn(|j| w[j * 32..(j + 1) * 32].try_into().unwrap()))
        .collect()
});
